#!/usr/bin/env python3
"""Guarded COSMOS Business Marketplace v9.5.4 installer.
Copies complete tested HTML only when the current file matches the known baseline.
This deliberately does NOT modify account, Life Worker, legal pages or D1.
"""
import argparse,hashlib,pathlib,sys,base64
BASE_SHA='080e096d7d470c17a708dc0691c13871534f1f25079ab7cb5c3b65c89749110d'
PAYLOAD_B64=''
parser=argparse.ArgumentParser();parser.add_argument('--mode',choices=['validate','apply'],default='validate');args=parser.parse_args()
p=pathlib.Path('cosmos-market-business.html')
if not p.exists():raise SystemExit('STOP: cosmos-market-business.html missing from GitHub root.')
original=p.read_bytes(); current=hashlib.sha256(original).hexdigest()
from base64 import b64decode
updated=b64decode(PAYLOAD_B64)
updated_hash=hashlib.sha256(updated).hexdigest()
if current==updated_hash:print('Already at v9.5.4. No changes needed.');sys.exit(0)
if current!=BASE_SHA:raise SystemExit('STOP: current marketplace HTML differs from known source; back up and compare before replacing. No files changed.')
if args.mode=='validate':print('PASS: expected source found; replacement is ready. No files changed.');sys.exit(0)
p.write_bytes(updated)
print('PASS: marketplace frontend updated to v9.5.4')
